#include <stdio.h>

#define CAP 16

/* ---- 存储结构：对使用者应当是隐藏的 ---- */
typedef struct { int data[CAP]; int top; } SeqStack;

/* ---- ADT Stack 的基本操作（接口）---- */
static void stk_init(SeqStack *s)         { s->top = -1; }
static int  stk_empty(const SeqStack *s)  { return s->top == -1; }
static int  stk_full(const SeqStack *s)   { return s->top == CAP - 1; }
static int  stk_push(SeqStack *s, int e)
{
    if (stk_full(s)) return 0;
    s->data[++s->top] = e;
    return 1;
}
static int  stk_pop(SeqStack *s, int *e)
{
    if (stk_empty(s)) return 0;
    *e = s->data[s->top--];
    return 1;
}

/* ---- 使用者：只调用接口，从不写 s.data[s.top] ---- */
int main(void)
{
    SeqStack s;
    int e;

    stk_init(&s);
    stk_push(&s, 10);
    stk_push(&s, 20);
    printf("empty=%d full=%d\n", stk_empty(&s), stk_full(&s));
    while (stk_pop(&s, &e)) printf("pop %d\n", e);
    printf("pop on empty -> %d\n", stk_pop(&s, &e));
    return 0;
}

#include <stdio.h>

static long cnt;

static void f_const(int n)  { (void)n; cnt += 1; }                       /* O(1)    */
static void f_log(int n)    { int i = n; while (i > 0) { cnt++; i /= 2; } } /* O(log n) */
static void f_lin(int n)    { int i; for (i = 0; i < n; i++) cnt++; }     /* O(n)    */
static void f_sqr(int n)    { int i, j;                                   /* O(n^2)  */
                              for (i = 0; i < n; i++)
                                  for (j = 0; j < n; j++) cnt++; }

int main(void)
{
    int ns[4] = {10, 100, 1000, 10000}, k;

    printf("%7s %8s %8s %8s %12s\n", "n", "O(1)", "O(logn)", "O(n)", "O(n^2)");
    for (k = 0; k < 4; k++) {
        int n = ns[k];
        long a, b, c, d;
        cnt = 0; f_const(n);  a = cnt;
        cnt = 0; f_log(n);    b = cnt;
        cnt = 0; f_lin(n);    c = cnt;
        cnt = 0; f_sqr(n);    d = cnt;
        printf("%7d %8ld %8ld %8ld %12ld\n", n, a, b, c, d);
    }
    return 0;
}

#include <stdio.h>

static long calls;

static long fib_rec(int n)                       /* 时间 O(2^n)，空间 O(n) */
{
    calls++;
    if (n <= 1) return n;
    return fib_rec(n - 1) + fib_rec(n - 2);
}

static long fib_loop(int n)                      /* 时间 O(n)，空间 O(1) */
{
    long a = 0, b = 1, t;
    int i;
    if (n <= 1) return n;
    for (i = 2; i <= n; i++) { t = a + b; a = b; b = t; }
    return b;
}

int main(void)
{
    int n = 30;

    calls = 0;
    printf("rec  fib(%d) = %ld  calls = %ld\n", n, fib_rec(n), calls);
    printf("loop fib(%d) = %ld  calls = %ld\n", n, fib_loop(n), 1L);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

int main(void)
{
    int seq[5] = { 10, 20, 30, 40, 50 };
    int i;

    /* 顺序存储：一整块连续内存，第 i 个元素的偏移恒为 i * sizeof(int) */
    printf("== 顺序存储：地址连续，可随机存取 ==\n");
    for (i = 0; i < 5; i++) {
        int offset = (int)((char *)&seq[i] - (char *)&seq[0]);
        printf("seq[%d] = %2d, 距首元素 %d 字节 (= %d * %d)\n",
               i, seq[i], offset, i, (int)sizeof(int));
    }

    /* 链式存储：结点各自 malloc，物理位置互不相邻，只能顺着 next 走 */
    printf("\n== 链式存储：结点分散，只能顺序存取 ==\n");
    Node *head = NULL;
    Node *tail = NULL;
    for (i = 1; i <= 3; i++) {
        Node *p = (Node *)malloc(sizeof(Node));
        if (p == NULL) {
            printf("内存分配失败\n");
            return 1;
        }
        p->data = i * 100;
        p->next = NULL;
        if (head == NULL) {
            head = p;
        } else {
            tail->next = p;
        }
        tail = p;
    }
    for (Node *p = head; p != NULL; p = p->next) {
        printf("顺着指针访问到 data = %d\n", p->data);
    }

    /* 链式存储必须显式回收；顺序存储的数组随作用域结束自动失效 */
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

#include <stdio.h>

/* 解法一：逐项累加，基本操作（加法）执行 n 次，时间复杂度 O(n) */
int sumByLoop(int n)
{
    int total = 0;
    int i;

    for (i = 1; i <= n; i++) {
        total += i;
    }
    return total;
}

/* 解法二：等差数列求和公式，基本操作执行常数次，时间复杂度 O(1) */
int sumByFormula(int n)
{
    return n * (n + 1) / 2;
}

int main(void)
{
    int n;

    /* 健壮性之一：scanf 必须检查返回值，输入不是整数时不能拿着未初始化的 n 往下算 */
    if (scanf("%d", &n) != 1) {
        printf("输入格式错误：期望一个整数\n");
        return 1;
    }

    /* 健壮性之二：对非法输入给出明确反应，而不是输出一个错得看不出来的结果 */
    if (n < 0) {
        printf("输入 %d 非法：n 应为非负整数\n", n);
        return 1;
    }

    /* 健壮性之三：先确认不会溢出再算。n > 46340 时 n*(n+1) 就已超出 int 上界 */
    if (n > 46340) {
        printf("n = %d 过大：n*(n+1) 会超出 int 表示范围，请改用 long long\n", n);
        return 1;
    }

    printf("循环版 1..%d 之和 = %d\n", n, sumByLoop(n));
    printf("公式版 1..%d 之和 = %d\n", n, sumByFormula(n));
    printf("加法次数：循环版 %d 次，公式版 0 次\n", n);
    return 0;
}
